"""Independent geometric and algebraic checks for the wallpaper implementation."""

import random
import unittest

from src.component import calculate_black_area_doubled as calculate


def unit_cell_area_doubled(x, y):
    """Determine colors from line-crossing parity, not from a tile table.

    Split a unit square on its anti-diagonal. The two triangle centroids
    have offsets (1/3, 1/3) and (2/3, 2/3). Each black triangle contributes
    one unit of doubled area. All divisions below use scaled integers.
    """
    return sum(
        (x + (3 * y + t) // 6 + (3 * (x + y) + 2 * t) // 6) % 2 == 0
        for t in (1, 2)
    )


class WallpaperTests(unittest.TestCase):
    def test_each_tile_cell_in_all_quadrants(self):
        tile = ((2, 1, 0, 1), (1, 2, 1, 0))
        for x in range(-12, 13):
            for y in range(-8, 9):
                self.assertEqual(calculate(x, y, x + 1, y + 1), tile[y % 2][x % 4])

    def test_all_small_rectangles_against_geometry(self):
        cells = {
            (x, y): unit_cell_area_doubled(x, y)
            for x in range(-6, 6)
            for y in range(-6, 6)
        }
        for a in range(-6, 6):
            for c in range(a + 1, 7):
                for b in range(-6, 6):
                    for d in range(b + 1, 7):
                        expected = sum(
                            cells[x, y] for x in range(a, c) for y in range(b, d)
                        )
                        self.assertEqual(calculate(a, b, c, d), expected, (a, b, c, d))

    def test_large_rectangles_periodicity_and_additivity(self):
        rng = random.Random(42)
        for _ in range(1000):
            a, c = sorted(rng.sample(range(-10**9 + 4, 10**9 - 4), 2))
            b, d = sorted(rng.sample(range(-10**9 + 2, 10**9 - 2), 2))
            result = calculate(a, b, c, d)
            self.assertIsInstance(result, int)
            self.assertTrue(0 <= result <= 2 * (c - a) * (d - b))
            self.assertEqual(result, calculate(a + 4, b + 2, c + 4, d + 2))
            if c - a > 1:
                mid = (a + c) // 2
                self.assertEqual(result, calculate(a, b, mid, d) + calculate(mid, b, c, d))
            if d - b > 1:
                mid = (b + d) // 2
                self.assertEqual(result, calculate(a, b, c, mid) + calculate(a, mid, c, d))

    def test_extreme_coordinates(self):
        limit = 10**9
        self.assertEqual(calculate(-limit, -limit, limit, limit), 4 * limit**2)
        for x in (-limit, limit - 1):
            for y in (-limit, limit - 1):
                self.assertEqual(calculate(x, y, x + 1, y + 1), unit_cell_area_doubled(x, y))
        self.assertEqual(calculate(-limit, -limit, limit, -limit + 1), 2 * limit)
        self.assertEqual(calculate(-limit, -limit, -limit + 1, limit), 3 * limit)


if __name__ == '__main__':
    unittest.main()
