from math import lcm
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th distinct positive multiple of any denomination.

    Coins cannot be mixed within an amount. ``coins`` contains 1-15 distinct
    positive integers, each at most 25, and ``k`` is between 1 and 2 * 10**9.
    The input list is not modified.

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    # Multiples of a redundant denomination already belong to a smaller one.
    denominations = []
    for coin in sorted(set(coins)):
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)

    smallest = denominations[0]
    if len(denominations) == 1:
        return smallest * k

    # The smallest denomination alone supplies k amounts by this upper bound.
    low, high = smallest, smallest * k

    # Inclusion-exclusion: an intersection of sets of multiples is precisely
    # the set of multiples of their LCM. Combine equal LCMs into one coefficient.
    coefficients = {}
    for coin in denominations:
        changes = {coin: 1}
        for multiple, coefficient in coefficients.items():
            intersection = lcm(multiple, coin)
            if intersection <= high:
                changes[intersection] = changes.get(intersection, 0) - coefficient
        for multiple, change in changes.items():
            coefficient = coefficients.get(multiple, 0) + change
            if coefficient:
                coefficients[multiple] = coefficient
            else:
                coefficients.pop(multiple, None)

    terms = tuple(coefficients.items())
    while low < high:
        middle = (low + high) // 2
        count = sum(coefficient * (middle // multiple)
                    for multiple, coefficient in terms)
        if count >= k:
            high = middle
        else:
            low = middle + 1
    return low
